,"limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"review_status":"approved","reviewed_at":"2026-11-03T08:04:14.628Z","review_batch":"nl-scale-20261102-038"}},{"ref":"w10","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL20448029W"},"before":null,"after":{"title":"Die Zeit des Skorpions","author_id":3346,"first_publish_year":2008,"open_library_id":"OL20448029W","cover_id":null,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL20448029W"}},{"ref":"e10","relation":"editions","key":{"open_library_edition_id":"OL38245143M"},"before":null,"after":{"work_id":"@w10","open_library_edition_id":"OL38245143M","isbn_13":"9789023993254","isbn_10":null,"title":"De woestijnloper","language":"dut","publisher":"Mozaïek"}},{"ref":"d10","relation":"catalog_work_descriptions","key":{"work_id":"@w10","language":"nl"},"before":null,"after":{"work_id":"@w10","language":"nl","bound_author_id":3346,"text":"In een toekomstig Europa heeft droogte grote gebieden onbewoonbaar gemaakt. De veertienjarige Tonia vermomt zich als jongen en sluit zich aan bij een groep Toearegs. Zij zijn onderweg naar een diep ondergronds waterreservoir dat voor veel mensen van levensbelang kan zijn. Hun opdracht wordt tegengewerkt door een machtige heerser uit het noorden. Tonia raakt betrokken bij een tocht waarin toegang tot water niet alleen over overleven gaat, maar ook bepaalt wie macht over anderen kan uitoefenen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://metadata.isbn.nl/1187608/de-woestijnloper.html","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p320320332"],"reference":"new-work-dossier-readings-038.json#208","checked_at":"2026-11-03T08:04:14.628Z","note":"MichaelWallner DieZeitDesSkorpions2008 per exactKBoriginal and Germanchildrenliterature review; Dutchpape